// ============================================================
// PARSE & FILTER EVENT — v1.5
// ============================================================
// DATA SHAPE AT THIS POINT:
// n8n webhook v2 wraps the raw POST body like this:
//   $input.first().json = {
//     headers: { ... },
//     params:  {},
//     query:   {},
//     body:    [ { eventId, objectId, propertyValue, ... } ]
//   }
// The actual HubSpot event is at .body[0]
//
// IMPORTANT — HubSpot Starter tier:
// previousPropertyValue is NOT sent by HubSpot Starter.
// Strategy: alert on any transition TO 'Active'.
// If previousPropertyValue IS present, also check it was
// Cold or Dormant (avoids alerting on brand-new contacts).
// ============================================================

const SEVERITY = {
  'Active':    1,
  'At Risk':   2,
  'Cold':      3,
  'Dormant':   4,
  'Opted Out': 5
};

function isImprovement(fromStatus, toStatus) {
  return (SEVERITY[toStatus] || 0) < (SEVERITY[fromStatus] || 0);
}

// Step 1: Extract the body — handle both wrapped and unwrapped payloads
const rawJson = $input.first().json;

// Router forwards the HubSpot event array directly as the POST body.
// n8n webhook v2 puts it under .body — but check both just in case.
let eventArray;
if (Array.isArray(rawJson.body)) {
  eventArray = rawJson.body;
} else if (Array.isArray(rawJson)) {
  eventArray = rawJson;
} else {
  // Single event object (some router configs send unwrapped)
  eventArray = [rawJson];
}

if (eventArray.length === 0) {
  console.log('[RE-ENGAGEMENT] Empty payload. Exiting.');
  return [];
}

const event = eventArray[0];
console.log('[RE-ENGAGEMENT] Raw event:', JSON.stringify(event));

const contactId      = String(event.objectId || '');
const newStatus      = event.propertyValue         || '';
const previousStatus = event.previousPropertyValue || '';
const occurredAt     = event.occurredAt
  ? new Date(event.occurredAt).toISOString()
  : new Date().toISOString();

if (!contactId || contactId === 'undefined') {
  console.log('[RE-ENGAGEMENT] No valid contactId. Exiting.');
  return [];
}

if (!newStatus) {
  console.log('[RE-ENGAGEMENT] No newStatus. Exiting.');
  return [];
}

// --- Filtering logic ---

// Case 1: previousStatus is available (HubSpot Pro+ or manual test)
if (previousStatus) {
  const ALERT_FROM = new Set(['Cold', 'Dormant']);
  if (!ALERT_FROM.has(previousStatus)) {
    console.log(`[RE-ENGAGEMENT] Previous '${previousStatus}' not Cold/Dormant. Exiting.`);
    return [];
  }
  if (!isImprovement(previousStatus, newStatus)) {
    console.log(`[RE-ENGAGEMENT] ${previousStatus} → ${newStatus} is not improvement. Exiting.`);
    return [];
  }
  console.log(`[RE-ENGAGEMENT] ⚡ Re-engagement (verified): ${contactId} ${previousStatus} → ${newStatus}`);
}
// Case 2: no previousStatus (HubSpot Starter) — alert only on Active
else {
  if (newStatus !== 'Active') {
    console.log(`[RE-ENGAGEMENT] No previous status + newStatus is '${newStatus}' (not Active). Exiting.`);
    return [];
  }
  console.log(`[RE-ENGAGEMENT] ⚡ Re-engagement (assumed): ${contactId} → ${newStatus} (no prior status available)`);
}

return [{
  json: {
    contactId,
    newStatus,
    previousStatus: previousStatus || 'Unknown',
    occurredAt
  }
}];

// ============================================================
// BUILD ALERT — v1.5
// ============================================================
// DATA SHAPE AT THIS POINT:
//
// $input.first().json = HubSpot contact response:
//   {
//     id: "208058893002",
//     properties: {
//       firstname, lastname, email, jobtitle, company,
//       canon_engagement_score, canon_days_since_engagement,
//       canon_seniority, canon_persona, canon_industry_tier
//     }
//   }
//
// $('Parse & Filter Event').first().json = our parsed event:
//   { contactId, newStatus, previousStatus, occurredAt }
//
// Cross-reference works here because this is a LINEAR chain:
// Parse & Filter → Fetch Contact → Build Alert
// n8n resolves $() references correctly in linear flows.
// ============================================================

const contact   = $input.first().json;
const eventData = $('Parse & Filter Event').first().json;

// Log what we received so we can debug if anything is still undefined
console.log('[BUILD ALERT] contact.id:', contact.id);
console.log('[BUILD ALERT] eventData:', JSON.stringify(eventData));

const p = contact.properties || {};

const { contactId, previousStatus, newStatus, occurredAt } = eventData;

// Contact fields with safe fallbacks
const name         = [p.firstname, p.lastname].filter(Boolean).join(' ') || '(No name)';
const email        = p.email    || '—';
const jobTitle     = p.jobtitle || '—';
const company      = p.company  || '—';
const score        = parseInt(p.canon_engagement_score       || '0', 10);
const daysSince    = parseInt(p.canon_days_since_engagement  || '0', 10);
const seniority    = p.canon_seniority     || '—';
const persona      = p.canon_persona       || '—';
const industryTier = p.canon_industry_tier || '—';

// Format silence duration
function formatSilence(days) {
  if (!days || days === 0) return 'recently';
  if (days < 30)  return `${days} days`;
  if (days < 365) return `${Math.floor(days / 30)} month${Math.floor(days / 30) === 1 ? '' : 's'}`;
  return `${Math.floor(days / 365)} year${Math.floor(days / 365) === 1 ? '' : 's'}`;
}

// Readable timestamp
const detectedAt = occurredAt
  ? new Date(occurredAt).toLocaleString('en-US', {
      month: 'short', day: 'numeric',
      hour: '2-digit', minute: '2-digit', timeZoneName: 'short'
    })
  : 'overnight';

// Alert config keyed by transition type
const ALERT_CONFIG = {
  'Dormant→Active':  { emoji: '🔥', urgency: 'High signal — went fully dark and just came back. Act quickly.' },
  'Dormant→At Risk': { emoji: '👀', urgency: 'Partial recovery from Dormant. Worth a light touch.' },
  'Dormant→Cold':    { emoji: '🧊', urgency: 'Still Cold but trending up from Dormant. Monitor closely.' },
  'Cold→Active':     { emoji: '⚡', urgency: 'Cold contact fully re-engaged. Good time to follow up.' },
  'Cold→At Risk':    { emoji: '📈', urgency: 'Moving in the right direction from Cold.' },
  'Unknown→Active':  { emoji: '🔔', urgency: 'Contact became Active. Previous status unavailable (HubSpot Starter).' }
};

const configKey = `${previousStatus}→${newStatus}`;
const config    = ALERT_CONFIG[configKey] || { emoji: '🔔', urgency: '' };

const hubspotUrl = `https://app-na2.hubspot.com/contacts/243444428/record/0-1/${contact.id || contactId}`;

// Build message lines
const contextParts = [];
if (jobTitle !== '—') contextParts.push(jobTitle);
if (company  !== '—') contextParts.push(company);
const contextLine = contextParts.join(' · ') || 'No title or company on record';

const enrichParts = [];
if (seniority    !== '—') enrichParts.push(`*${seniority}*`);
if (persona      !== '—') enrichParts.push(persona);
if (industryTier !== '—') enrichParts.push(`ICP: ${industryTier}`);
const enrichLine = enrichParts.length > 0 ? enrichParts.join('  ·  ') : null;

const lines = [];
lines.push(`${config.emoji} *Re-engagement detected: ${previousStatus} → ${newStatus}*`);
lines.push('');
lines.push(`*<${hubspotUrl}|${name}>*`);
lines.push(contextLine);
if (email !== '—') lines.push(email);
if (enrichLine) {
  lines.push('');
  lines.push(enrichLine);
}
lines.push('');
lines.push(`*Previous score:* ${score}/100  ·  *Was silent for:* ${formatSilence(daysSince)}`);
lines.push(`*Detected:* ${detectedAt} _(via nightly scorer)_`);
if (config.urgency) {
  lines.push('');
  lines.push(`_${config.urgency}_`);
}

console.log(`[BUILD ALERT] Posting: ${name} (${previousStatus} → ${newStatus})`);

return [{ json: { slackMessage: lines.join('\n'), contactName: name } }];

const error = $input.first().json;
console.error('[RE-ENGAGEMENT ERROR]', JSON.stringify({
  workflow:  'Re-engagement Alert v1.5',
  error:     error.message || 'Unknown error',
  node:      error.node?.name || 'Unknown',
  timestamp: new Date().toISOString()
}));
return [{ json: { logged: true } }];
